use serde_json::json;
use sha2::{Digest,Sha256};
use std::{hint::black_box,time::Instant};
use zopro_gaussian_fr_probe::experiment::{Input,reference};
fn main(){let args:Vec<_>=std::env::args().collect();assert_eq!(args.len(),4);let mode=&args[1];let pattern=&args[2];let n:usize=args[3].parse().unwrap();assert!(n>0);let input=Input::new();let ordinary=input.ordinary();let gaussian=input.gaussian();let use_gaussian=mode.starts_with("gaussian");let direct=mode.ends_with("r4");assert!(["ordinary","ordinary-copy","gaussian","ordinary-r2","ordinary-r2-copy","ordinary-r4","gaussian-r2","gaussian-r4"].contains(&mode.as_str()));
 for _ in 0..3 {if use_gaussian{black_box(gaussian.execute(pattern,direct,2000));}else{black_box(ordinary.execute(pattern,direct,2000));}}
 let start=Instant::now();let (elapsed,output)=if use_gaussian{let values=gaussian.execute(pattern,direct,n);let elapsed=start.elapsed();(elapsed,values.into_iter().map(|v|input.decode(v)).collect::<Vec<_>>())}else{let values=ordinary.execute(pattern,direct,n);let elapsed=start.elapsed();(elapsed,values.into_iter().map(|v|v.get()).collect::<Vec<_>>())};
 let want=reference(&input,pattern,n);assert_eq!(output,want);let fields=output.len()*8;let bytes:Vec<_>=output.iter().flatten().flat_map(|v|v.to_canonical().into_iter().flat_map(u64::to_le_bytes)).collect();assert_eq!(bytes.len(),fields*32);let divisor=n*8*if pattern=="streams4"{4}else{1};println!("RESULT {}",json!({"pattern":pattern,"mode":mode,"iterations":n,"priming_calls":3,"prime_iterations":2000,"elapsed_ns":elapsed.as_nanos(),"ns_per_unit":elapsed.as_nanos()as f64/divisor as f64,"unit":if pattern=="butterfly"{"four_point_butterfly_lane"}else{"field_lane_update"},"checked_fields":fields,"output_sha256":format!("{:x}",Sha256::digest(bytes)),"input_conversion_in_timer":false,"output_conversion_in_timer":false,"result_vector_allocation_in_timer":true,"internally_verified":true,"SDK_requests":0}));}
